const { ethers } = require('/tmp/node_modules/ethers');

async function test() {
  const pSep = new ethers.JsonRpcProvider('https://sepolia-rollup.arbitrum.io/rpc');
  // childGatewayRouter on Arb Sepolia: 0x9fDD1C4E4AA24EEc1d913FABea925594a20d43C7
  const routerAbi = ['function calculateL2TokenAddress(address l1ERC20) view returns (address)'];
  const router = new ethers.Contract('0x9fDD1C4E4AA24EEc1d913FABea925594a20d43C7', routerAbi, pSep);
  const l1USDC = '0x1c7D4B196Cb0C7B01d743Fbc6116a902379C7238'; // Sepolia USDC
  try {
    const l2Token = await router.calculateL2TokenAddress(l1USDC);
    console.log('Calculated L2 token for Sepolia USDC:', l2Token);
    const code = await pSep.getCode(l2Token);
    console.log('Code exists:', code !== '0x');
    if (code !== '0x') {
      const tokenAbi = ['function symbol() view returns (string)', 'function name() view returns (string)'];
      const token = new ethers.Contract(l2Token, tokenAbi, pSep);
      console.log('Symbol:', await token.symbol(), 'Name:', await token.name());
    }
  } catch (e) {
    console.error(e);
  }
}
test();
"

