// calculateL2TokenAddress(address) selector is 0xaa271e1a
async function test() {
  const l1USDC = '1c7D4B196Cb0C7B01d743Fbc6116a902379C7238'.padStart(64, '0');
  const res = await fetch('https://sepolia-rollup.arbitrum.io/rpc', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      jsonrpc: '2.0',
      method: 'eth_call',
      params: [{ to: '0x9fDD1C4E4AA24EEc1d913FABea925594a20d43C7', data: '0xaa271e1a' + l1USDC }, 'latest'],
      id: 1
    })
  }).then(r => r.json());
  console.log('calculateL2TokenAddress result:', res);
  if (res.result) {
    const l2Addr = '0x' + res.result.slice(-40);
    console.log('L2 addr:', l2Addr);
    const code = await fetch('https://sepolia-rollup.arbitrum.io/rpc', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ jsonrpc: '2.0', method: 'eth_getCode', params: [l2Addr, 'latest'], id: 2 })
    }).then(r => r.json());
    console.log('code:', code);
  }
}
test();
"

